import os
from typing import Dict, Any, Tuple

from openai import OpenAI

# Provider-specific environment variable: OPENAI_API_KEY
_client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

# Category thresholds are maximum allowed scores in [0.0, 1.0].
# If a category score exceeds its threshold, the text is blocked.
DEFAULT_THRESHOLDS: Dict[str, float] = {
    "harassment": 0.7,
    "harassment/threatening": 0.4,
    "hate": 0.7,
    "hate/threatening": 0.3,
    "self-harm": 0.3,
    "self-harm/instructions": 0.2,
    "self-harm/intent": 0.2,
    "sexual": 0.8,
    "sexual/minors": 0.01,
    "violence": 0.7,
    "violence/graphic": 0.3,
}

def _extract_category_scores(result: Any) -> Dict[str, float]:
    scores = getattr(result, "category_scores", None)
    if scores is None:
        return {}

    if hasattr(scores, "model_dump"):
        raw = scores.model_dump()
    elif isinstance(scores, dict):
        raw = scores
    else:
        raw = scores.__dict__

    normalized: Dict[str, float] = {}
    for k, v in raw.items():
        if v is None:
            continue
        normalized[k.replace("_", "/")] = float(v)
    return normalized

def check_text_safety(
    text: str,
    thresholds: Dict[str, float] | None = None,
) -> Dict[str, Any]:
    if not text:
        return {
            "allowed": True,
            "blocked_categories": {},
            "scores": {},
            "thresholds": thresholds or DEFAULT_THRESHOLDS,
            "provider": "openai",
            "model": "omni-moderation-latest",
        }

    applied_thresholds = dict(DEFAULT_THRESHOLDS)
    if thresholds:
        applied_thresholds.update(thresholds)

    response = _client.moderations.create(
        model="omni-moderation-latest",
        input=text,
    )

    result = response.results[0]
    scores = _extract_category_scores(result)

    blocked_categories: Dict[str, Dict[str, float]] = {}
    for category, threshold in applied_thresholds.items():
        score = scores.get(category)
        if score is not None and score > threshold:
            blocked_categories[category] = {
                "score": score,
                "threshold": threshold,
            }

    return {
        "allowed": len(blocked_categories) == 0,
        "blocked_categories": blocked_categories,
        "scores": scores,
        "thresholds": applied_thresholds,
        "provider": "openai",
        "model": "omni-moderation-latest",
    }
